#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include <torch/torch.h>

namespace ascend_kernel {

at::Tensor histc(const at::Tensor& self, int64_t bins, float min_val, float max_val) {
    // Input validation
    TORCH_CHECK(self.is_contiguous(), "histc: input must be contiguous");
    TORCH_CHECK(bins > 0, "histc: bins must be positive");
    TORCH_CHECK(min_val < max_val, "histc: min must be less than max");

    int64_t num_elements = self.numel();
    auto output = at::zeros({bins}, at::TensorOptions().dtype(at::kInt).device(self.device()));

    if (num_elements == 0) {
        return output;
    }

    // Get platform info
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t core_num = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());

    uint64_t ub_size;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ub_size);

    // Block-level tiling
    int64_t block_size = 2048;  // elements per block
    int64_t num_blocks = (num_elements + block_size - 1) / block_size;
    int64_t used_core_num = std::min(core_num, num_blocks);
    int64_t tasks_per_core = (num_blocks + used_core_num - 1) / used_core_num;

    // Workspace for local histograms: [num_blocks, bins]
    auto workspace = at::zeros({num_blocks, bins}, at::TensorOptions().dtype(at::kInt).device(self.device()));

    // Tiling parameters
    int64_t tile_length = 256;  // elements per tile
    int64_t dtype_size = (self.dtype() == at::kHalf) ? 2 : 4;
    int64_t buffer_coefficient = (dtype_size == 4) ? 20 : 16;

    // Calculate aligned lengths
    int64_t total_length = num_elements;
    int64_t total_length_core_align = ((total_length + used_core_num - 1) / used_core_num + 31) / 32 * 32;
    int64_t former_num = total_length / total_length_core_align;
    int64_t former_length = total_length_core_align;
    int64_t tail_num = total_length % total_length_core_align;
    int64_t tail_length = tail_num;

    // Cast min/max to float for kernel
    float min_val_f = min_val;
    float max_val_f = max_val;
    int64_t bins_i = bins;

    // Launch kernel
    if (self.dtype() == at::kFloat) {
        EXEC_KERNEL_CMD(histc_fp32, used_core_num, self, output, workspace,
                        total_length, former_num, former_length, tail_length, tile_length,
                        bins_i, min_val_f, max_val_f);
    } else if (self.dtype() == at::kHalf) {
        EXEC_KERNEL_CMD(histc_fp16, used_core_num, self, output, workspace,
                        total_length, former_num, former_length, tail_length, tile_length,
                        bins_i, min_val_f, max_val_f);
    } else {
        TORCH_CHECK(false, "histc: unsupported dtype, only float32 and float16 are supported");
    }

    return output;
}

} // namespace ascend_kernel
