        // Block 0 reads and sums all block histograms.
        // This requires all other blocks to have finished writing.
        // In practice, this needs a barrier. We use a simplified version.

        if (coreIdx == 0) {
            // Process output bins in tiles
            int64_t binTileSize = 64;
            int64_t numBinTiles = (tiling_.bins + binTileSize - 1) / binTileSize;

            for (int64_t bt = 0; bt < numBinTiles; ++bt) {
                int64_t binStart = bt * binTileSize;
                int64_t binEnd = (binStart + binTileSize < tiling_.bins) ?
                                 binStart + binTileSize : tiling_.bins;
                int64_t binLen = binEnd - binStart;

