    tiling->totalLength = *reinterpret_cast<int64_t*>(ptr);
    tiling->bins = *reinterpret_cast<int64_t*>(ptr + 2);
    tiling->min_val = *reinterpret_cast<float*>(ptr + 4);
    tiling->max_val = *reinterpret_cast<float*>(ptr + 5);
    tiling->tileLength = *reinterpret_cast<int64_t*>(ptr + 6);
}

template <typename T>
class KernelHistc {
public:
    __aicore__ inline KernelHistc() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR out, GM_ADDR tiling) {
        CopyTiling(&tiling_, tiling);

        xGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x));
        outGm.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(out));

        // Initialize queues with double buffer
        pipe.InitBuffer(inQueueX, BUFFER_NUM, tiling_.tileLength * sizeof(T));
    }

    __aicore__ inline void Process() {
        int64_t coreIdx = GetBlockIdx();
        int64_t coreNum = GetBlockNum();

        // Each core processes a portion of the input
        int64_t elemsPerCore = (tiling_.totalLength + coreNum - 1) / coreNum;
        int64_t elemStart = coreIdx * elemsPerCore;
        int64_t elemEnd = (elemStart + elemsPerCore < tiling_.totalLength) ?
                          elemStart + elemsPerCore : tiling_.totalLength;
        int64_t curCoreElems = elemEnd - elemStart;

        if (curCoreElems <= 0) {
            return;
        }

        // Precompute scale factor
        float range = tiling_.max_val - tiling_.min_val;
        float scale = (range > 0.0f) ? static_cast<float>(tiling_.bins) / range : 0.0f;

        // Each core maintains a local histogram in UB
        // We use TBuf for the histogram since it's not directly copied from/to GM
        TBuf<TPosition::VECCALC> histBuf;
        pipe.InitBuffer(histBuf, tiling_.bins * sizeof(int32_t));
        LocalTensor<int32_t> histLocal = histBuf.Get<int32_t>();
        AscendC::Duplicate(histLocal, 0, tiling_.bins);

        // Process elements in tiles
        int64_t numTiles = (curCoreElems + tiling_.tileLength - 1) / tiling_.tileLength;

        for (int64_t t = 0; t < numTiles; ++t) {
            int64_t tileStart = elemStart + t * tiling_.tileLength;
            int64_t tileEnd = (tileStart + tiling_.tileLength < elemEnd) ?
                              tileStart + tiling_.tileLength : elemEnd;
            int64_t tileLen = tileEnd - tileStart;

            // Copy input tile from GM to UB
            LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
            AscendC::DataCopyPad(xLocal, xGm[tileStart],
                {1, static_cast<uint16_t>(tileLen * sizeof(T)), 0, 0});
            inQueueX.EnQue(xLocal);

            // Deque for compute
            LocalTensor<T> xIn = inQueueX.DeQue<T>();

            // Cast to float32 if needed for computation
            if constexpr (sizeof(T) == sizeof(half)) {
                // FP16: cast to float32 then compute
                TBuf<TPosition::VECCALC> castBuf;
                pipe.InitBuffer(castBuf, tiling_.tileLength * sizeof(float));
                LocalTensor<float> xFp32 = castBuf.Get<float>();
                AscendC::Cast(xFp32, xIn, AscendC::RoundMode::CAST_NONE, tileLen);

                // Scalar loop to compute bin indices and accumulate
                for (int64_t i = 0; i < tileLen; ++i) {
                    float val = xFp32.GetValue(i);
                    float shifted = val - tiling_.min_val;
                    float scaled = shifted * scale;
                    int32_t binIdx = static_cast<int32_t>(scaled);
                    if (binIdx < 0) binIdx = 0;
                    if (binIdx >= tiling_.bins) binIdx = tiling_.bins - 1;

                    int32_t count = histLocal.GetValue(binIdx);
                    histLocal.SetValue(binIdx, count + 1);
                }
            } else {
                // FP32: direct computation
                for (int64_t i = 0; i < tileLen; ++i) {
                    float val = static_cast<float>(xIn.GetValue(i));
                    float shifted = val - tiling_.min_val;
                    float scaled = shifted * scale;
                    int32_t binIdx = static_cast<int32_t>(scaled);
                    if (binIdx < 0) binIdx = 0;
                    if (binIdx >= tiling_.bins) binIdx = tiling_.bins - 1;

                    int32_t count = histLocal.GetValue(binIdx);
                    histLocal.SetValue(binIdx, count + 1);
                }
            }

            inQueueX.FreeTensor(xIn);
        }

        // Write local histogram to output using atomic add
