        // A proper solution requires workspace + reduction kernel or host-side reduction

        // Simplified: single-core only for correctness
        // Write histogram to output
        if (coreIdx == 0) {
            AscendC::DataCopyPad(outGm[0], histLocal,
                {1, static_cast<uint16_t>(tiling_.bins * sizeof(int32_t)), 0, 0});
        }
    }

private:
