#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include <torch/library.h>
#include <torch/torch.h>

namespace ascend_kernel {

at::Tensor histc(const at::Tensor& self, int64_t bins, float min_val, float max_val) {
    // Input validation
    TORCH_CHECK(self.is_contiguous(), "histc: input must be contiguous");
    TORCH_CHECK(bins > 0, "histc: bins must be positive");
    TORCH_CHECK(min_val < max_val, "histc: min must be less than max");

    int64_t num_elements = self.numel();
    auto output = at::zeros({bins}, at::TensorOptions().dtype(at::kInt).device(self.device()));

    if (num_elements == 0) {
        return output;
    }

    // Get platform info
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t core_num = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());

    uint64_t ub_size;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ub_size);

    // Use single core for correctness (histc requires accumulation to shared bins)
    int64_t used_core_num = 1;

    // Tiling parameters
    int64_t tile_length = 256;  // elements per tile

    // Prepare tiling data on device
    // Layout: [totalLength, bins, min_val, max_val, tileLength, coreNum]
    auto tiling_data = at::zeros({10}, at::TensorOptions().dtype(at::kInt).device(self.device()));
    auto tiling_cpu = at::zeros({10}, at::TensorOptions().dtype(at::kInt));
    int64_t* tiling_ptr = tiling_cpu.data_ptr<int64_t>();
    tiling_ptr[0] = num_elements;
    tiling_ptr[1] = bins;
    *reinterpret_cast<float*>(&tiling_ptr[2]) = min_val;
    *reinterpret_cast<float*>(&tiling_ptr[3]) = max_val;
    tiling_ptr[4] = tile_length;
    tiling_ptr[5] = used_core_num;
    tiling_data.copy_(tiling_cpu);

    // Workspace for local histograms: [coreNum, bins]
    auto workspace = at::zeros({used_core_num, bins}, at::TensorOptions().dtype(at::kInt).device(self.device()));

    // Cast to left values for EXEC_KERNEL_CMD
    float min_val_f = min_val;
    float max_val_f = max_val;
    int64_t bins_i = bins;
    int64_t num_elements_i = num_elements;

    // Launch kernel
    if (self.dtype() == at::kFloat) {
        EXEC_KERNEL_CMD(histc_fp32, used_core_num, self, workspace, tiling_data,
                        num_elements_i, bins_i, min_val_f, max_val_f);
    } else if (self.dtype() == at::kHalf) {
        EXEC_KERNEL_CMD(histc_fp16, used_core_num, self, workspace, tiling_data,
                        num_elements_i, bins_i, min_val_f, max_val_f);
    } else {
        TORCH_CHECK(false, "histc: unsupported dtype, only float32 and float16 are supported");
    }

    // Reduce workspace to output on host
    // workspace shape: [coreNum, bins]
    // Sum along dim 0 to get final histogram
    output = workspace.sum(0);

    return output;
}

} // namespace ascend_kernel

TORCH_LIBRARY_FRAGMENT(npu, m) {
    m.def("histc(Tensor self, int bins, float min_val, float max_val) -> Tensor");
}

TORCH_LIBRARY_IMPL(npu, PrivateUse1, m) {
    m.impl("histc", TORCH_FN(ascend_kernel::histc));
}
